inputs = ['byc', 'fddef', 'cazye', 'kxwh', 'cxy']
outputs = ['bhc', 'fddef', 'cazhe', 'kxwh', 'cfg']

# Let's manually trace through what happens in each case:
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find exactly what changed
        changes = []
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                changes.append((j, char_in, char_out))
        if len(inp) != len(outp):
            # Handle length differences
            if len(inp) > len(outp):
                # Removed characters
                for j in range(len(outp)):
                    if j >= len(inp) or inp[j] != outp[j]:
                        changes.append((j, inp[j], ""))
                # Check remaining characters
                if len(inp) > len(outp):
                    for j in range(len(outp), len(inp)):
                        changes.append((j, inp[j], ""))
            else:
                # Added characters  
                for j in range(len(inp)):
                    if inp[j] != outp[j]:
                        changes.append((j, "", outp[j]))
                # Check remaining characters
                if len(outp) > len(inp):
                    for j in range(len(inp), len(outp)):
                        changes.append((j, "", outp[j]))
        print(f"  Changes: {changes}")
    else:
        print("  No change")

# Now let's see if there's a consistent pattern
print("\nLooking for consistent rules:")
print("Positions that change:")
positions_changed = set()
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                positions_changed.add(j)
print(positions_changed)

